"""Interactive wizard that writes `harness.yaml`.

No static framework / package-manager / test-runner catalogues. Wizard collects
user input verbatim. Composer auto-synthesises `<framework>-patterns` skill
scaffolds for any framework name the user types — teams fill the body.

Falls back to non-interactive defaults when stdin is not a TTY (e.g. CI), so the
command can be scripted.
"""

from __future__ import annotations

import re
import sys
from collections import OrderedDict
from pathlib import Path
from typing import Any, get_args

import questionary
from rich.console import Console
from ruamel.yaml import YAML
from ruamel.yaml.scalarstring import DoubleQuotedScalarString

from harness.config.models import (
    Ci,
    DesignTool,
    DocTracker,
    GovernanceProfile,
    IssueTracker,
    Vcs,
)

_console = Console()
_err = Console(stderr=True)


_FRAMEWORK_NAME_RE = re.compile(r"^[a-z][a-z0-9-]*$")


def _slugify_project_name(raw: str) -> str:
    """Convert any user input to a valid Pydantic `name` field value.

    Pydantic requires `^[a-z][a-z0-9-]*$`. Apply the same rules robustly:
    - lowercase
    - CamelCase → kebab-case (PlatformAlpha → platform-alpha)
    - underscores, spaces, dots → hyphens
    - strip non-alphanumerics
    - collapse repeated hyphens; strip leading/trailing hyphens
    - if first char is a digit, prefix `p-`
    """
    s = raw.strip()
    # CamelCase split: insert hyphen before each uppercase that follows lowercase
    # or digit, then before a sequence of uppercase letters followed by lowercase.
    s = re.sub(r"(?<=[a-z0-9])([A-Z])", r"-\1", s)
    s = re.sub(r"([A-Z]+)([A-Z][a-z])", r"\1-\2", s)
    s = s.lower()
    s = re.sub(r"[^a-z0-9]+", "-", s)
    s = re.sub(r"-{2,}", "-", s).strip("-")
    if not s:
        s = "project"
    if s[0].isdigit():
        s = "p-" + s
    return s


def _enum_choices(literal_type) -> list[str]:
    """Pull literal values out of a `typing.Literal[...]` alias."""
    return list(get_args(literal_type))


def _parse_stack_entry(entry: str) -> tuple[str | None, str | None]:
    """Parse `name:version` or `name`. Returns (framework, version_or_None).
    Returns (None, None) only when the framework name is malformed."""
    parts = entry.split(":", 1)
    framework = parts[0].strip().lower()
    version = parts[1].strip() if len(parts) == 2 and parts[1].strip() else None
    if not _FRAMEWORK_NAME_RE.fullmatch(framework):
        return None, None
    return framework, version


# ---- wizard ----------------------------------------------------------------


_SUPPORTED_TARGETS = ["claude-code", "codex", "copilot", "gemini", "cursor", "antigravity"]
_V1_TARGET = "claude-code"
# Targets offered in the interactive prompt. Only the shippable target is shown;
# the rest stay recognised by --target (with a "planned" message) but are hidden
# from the picker until their emitters land.
_PROMPT_TARGETS = [_V1_TARGET]
_TARGET_LABELS = {
    "claude-code": "Claude Code",
    "codex":       "OpenAI Codex CLI  (v2 — planned)",
    "copilot":     "GitHub Copilot  (v2 — planned)",
    "gemini":      "Gemini CLI  (v2 — planned)",
    "cursor":      "Cursor  (v2 — planned)",
    "antigravity": "Google Antigravity  (v2 — planned)",
}


def prompt_target(*, force_prompt: bool = False) -> str | None:
    """Ask the user which AI tool target to emit for. Returns target literal or None.

    Behaviour:
        - If stdin is not a TTY and not force_prompt → returns "claude-code" silently.
        - Else: questionary select with all six targets.
        - If user picks non-claude-code → prints "planned for v2" message and returns
          the picked value (caller decides whether to abort).
    """
    if not force_prompt and not sys.stdin.isatty():
        return _V1_TARGET

    _choices = [
        questionary.Choice(_TARGET_LABELS[t], value=t)
        for t in _PROMPT_TARGETS
    ]
    # questionary's default must be a Choice object (or its label string), not the value.
    _default_choice = next(c for c in _choices if c.value == _V1_TARGET)
    choice = questionary.select(
        "Target AI tool:",
        choices=_choices,
        default=_default_choice,
    ).unsafe_ask()
    if choice is None:
        return None
    return choice


def _print_target_unsupported(target: str) -> None:
    """Tell the user a non-v1 target is planned but not yet shipped."""
    _err.print(
        f"[red]Target {target!r} is planned for v2 but not yet supported.[/red]\n"
        f"[dim]v1 supports only [bold]claude-code[/bold]. "
        f"The harness IR is tool-agnostic; emitters for codex / copilot / gemini / cursor / "
        f"antigravity are stubbed and land in a future release.\n"
        f"Re-run with [bold]--target claude-code[/bold] to proceed today.[/dim]"
    )


def run_wizard(
    out_path: Path,
    *,
    force: bool = False,
    interactive: bool = False,
    non_interactive: bool = False,  # deprecated; kept for backwards-compat
    target: str | None = None,
) -> int:
    """Drive the wizard and write `out_path`. Returns process exit code.

    Default behaviour (no flags): silent — writes a minimal config with
    empty stacks and safe-default integrations. User adds stacks /
    integrations / governance later via `harness add`.

    Flags:
        interactive: explicitly run the 10-prompt questionary wizard.
        non_interactive: backwards-compat alias for the default silent mode.
        target: explicit emitter target. When None and stdin is a TTY, prompts
            for selection. When None and not a TTY, defaults to claude-code.
    """
    if out_path.exists() and not force:
        _err.print(f"[red]{out_path} already exists; pass --force to overwrite.[/red]")
        return 1

    # Resolve target. CLI flag wins; otherwise prompt (TTY) or default (non-TTY).
    if target is None:
        target = prompt_target()
    if target is None:
        _err.print("[red]No target selected. Aborting.[/red]")
        return 1
    if target not in _SUPPORTED_TARGETS:
        _err.print(f"[red]Unknown target {target!r}. Valid: {_SUPPORTED_TARGETS}.[/red]")
        return 1
    if target != _V1_TARGET:
        _print_target_unsupported(target)
        return 1

    cfg = _interactive() if interactive and sys.stdin.isatty() else _build_default_config()

    cfg["targets"] = [target]

    _write_yaml(out_path, cfg)
    _console.print(f"[green]wrote[/green] {out_path}")
    if cfg.get("stacks"):
        _console.print("[dim]Next: harness generate[/dim]")
    else:
        _console.print(
            "[dim]Next: [bold]harness generate[/bold], then [bold]harness add stack <name>:<version>[/bold] "
            "when you're ready to wire a framework. Or use the slash commands "
            "(/arh-intake, /arh-validate-story, /arh-research, /arh-plan-requirements) right away — "
            "they work without a stack.[/dim]"
        )
    return 0


def _interactive() -> dict[str, Any]:
    _console.print("[bold]harness init[/bold] — interactive harness wizard\n")

    # 1. project
    raw_name = questionary.text(
        "Project name (lowercase letters, digits, hyphens; uppercase auto-converted):",
        validate=lambda v: bool(v) and v.strip() != "",
    ).unsafe_ask()
    name = _slugify_project_name(raw_name)
    if name != raw_name:
        _console.print(f"  [dim]normalised:[/dim] {raw_name!r} → [bold]{name}[/bold]")
    description = questionary.text(
        "Project description (one line):",
        default=f"{name} harness",
    ).unsafe_ask()

    # 2. tech stacks — optional at init time. User can defer and add later
    # via `harness add stack <name>:<version>`. Blank-on-first-prompt = defer.
    # /arh-intake, /arh-validate-story, /arh-research, /arh-plan-requirements work without
    # stacks. /arh-plan-implementation onwards requires at least one stack (gated
    # by phase-preconditions).
    stacks: list[dict[str, Any]] = []
    _console.print(
        "\n[dim]Tech stacks (optional — defer with blank Enter and add later via "
        "[bold]harness add stack <name>:<version>[/bold]).\nFormat: [bold]name:version[/bold] "
        "(e.g. nextjs:14, expo:55, fastapi:0.115).[/dim]"
    )
    while True:
        entry = questionary.text(
            f"Tech stack #{len(stacks) + 1} (name:version, blank to finish/skip):",
        ).unsafe_ask()
        entry = (entry or "").strip()
        if not entry:
            if not stacks:
                _console.print(
                    "[dim]  no stacks declared — defer to "
                    "[bold]harness add stack <name>:<version>[/bold] before "
                    "/arh-plan-implementation.[/dim]"
                )
            break

        framework, version = _parse_stack_entry(entry)
        if framework is None:
            _err.print(
                f"[red]Invalid framework name {entry!r}. "
                "Use lowercase letters, digits, and hyphens.[/red]"
            )
            continue

        stack_id = questionary.text(
            "Stack id (lowercase, hyphens):",
            default=_default_stack_id(framework, stacks),
        ).unsafe_ask()

        package_manager = questionary.text(
            "Package manager (blank to skip):",
            default="",
        ).unsafe_ask().strip()

        test_runner = questionary.text(
            "Test runner (blank to skip):",
            default="",
        ).unsafe_ask().strip()

        paths_input = questionary.text(
            "Paths (comma-separated globs):",
            default="**",
        ).unsafe_ask()
        paths_list = [p.strip() for p in paths_input.split(",") if p.strip()]

        stacks.append({
            "id": stack_id,
            "framework": framework,
            **({"version": version} if version else {}),
            **({"package_manager": package_manager} if package_manager else {}),
            **({"test_runner": test_runner} if test_runner else {}),
            "paths": paths_list,
        })
        _console.print(
            f"[green]  ✓ {framework}{':' + version if version else ''}[/green] "
            f"[dim](pm={package_manager or '-'}, test={test_runner or '-'})[/dim]"
        )

    # 3. integrations
    issue_tracker = questionary.select(
        "Issue tracker:",
        choices=_enum_choices(IssueTracker),
        default="none",
    ).unsafe_ask()
    doc_tracker = questionary.select(
        "Doc tracker:",
        choices=_enum_choices(DocTracker),
        default="local",
    ).unsafe_ask()
    design = questionary.select(
        "Design tool:",
        choices=_enum_choices(DesignTool),
        default="none",
    ).unsafe_ask()
    vcs = questionary.select("VCS:", choices=_enum_choices(Vcs), default="github").unsafe_ask()
    ci = questionary.select("CI provider:", choices=_enum_choices(Ci), default="github-actions").unsafe_ask()

    # 4. governance
    profile = questionary.select(
        "Governance profile:",
        choices=_enum_choices(GovernanceProfile),
        default="standard",
    ).unsafe_ask()

    # 5. domains — always shown, prominent
    from harness.commands.add import _load_bundled_domains
    bundled_domains = _load_bundled_domains()
    domain_choices = [
        questionary.Choice(
            f"{p['domain']:14} — {p['key_concerns'][0] if p.get('key_concerns') else ''}",
            value=p["domain"],
        )
        for p in bundled_domains
    ]
    _console.print(
        "\n[bold]Domain[/bold] — shapes PRD compliance questions and domain research.\n"
        "[dim]Leave all unchecked for a general product (no domain-specific behavior).\n"
        "Custom domains (e.g. pharmaceutical) → run 'harness add domain <name>' after init.[/dim]"
    )
    selected_domains: list[str] = questionary.checkbox(
        "Which domain(s) apply to this project?",
        choices=domain_choices,
    ).unsafe_ask() or []

    # 6. permissions allowlist — leave empty; user adds after if needed.
    return _assemble_config(
        name=name,
        description=description,
        stacks=stacks,
        issue_tracker=issue_tracker,
        doc_tracker=doc_tracker,
        design=design,
        vcs=vcs,
        ci=ci,
        profile=profile,
        allow_extra=[],
        selected_domains=selected_domains,
    )


def _build_default_config() -> dict[str, Any]:
    """Silent default config. Empty stacks (deferred — add via `harness add stack`),
    safe-default integrations (none / local / github / github-actions), standard
    governance. Stack declaration is deferred to the planning phase, not at init.
    """
    return _assemble_config(
        name="my-app",
        description="harness scaffolded by harness init",
        stacks=[],
        issue_tracker="none",
        doc_tracker="local",
        design="none",
        vcs="github",
        ci="github-actions",
        profile="standard",
        allow_extra=[],
    )


def _assemble_config(
    *,
    name: str,
    description: str,
    stacks: list[dict[str, Any]],
    issue_tracker: str,
    doc_tracker: str,
    design: str,
    vcs: str,
    ci: str,
    profile: str,
    allow_extra: list[str],
    selected_domains: list[str] | None = None,
) -> dict[str, Any]:
    cfg: OrderedDict[str, Any] = OrderedDict()
    cfg["apiVersion"] = "harness.dev/v1"
    cfg["kind"] = "Harness"
    cfg["template_version"] = "0.1.0"
    cfg["project"] = {"name": name, "description": description}
    cfg["stacks"] = stacks
    cfg["integrations"] = {
        "doc_tracker": doc_tracker,
        "issue_tracker": issue_tracker,
        "design": design,
        "vcs": vcs,
        "ci": ci,
    }
    cfg["governance"] = {"profile": profile}
    if selected_domains:
        cfg["domains"] = {"selected": selected_domains}
    cfg["permissions"] = {"allow_extra": allow_extra}
    cfg["targets"] = ["claude-code"]
    return cfg


# ---- helpers --------------------------------------------------------------


def _default_stack_id(framework: str, existing: list[dict[str, Any]]) -> str:
    """Generate a non-colliding stack id from the framework name."""
    base = framework
    used = {s["id"] for s in existing}
    if base not in used:
        return base
    n = 2
    while f"{base}-{n}" in used:
        n += 1
    return f"{base}-{n}"


def _write_yaml(out_path: Path, cfg: dict[str, Any]) -> None:
    """Write the config as YAML with stable key order."""
    yaml = YAML()
    yaml.indent(mapping=2, sequence=4, offset=2)
    yaml.width = 120
    cfg = dict(cfg)
    if "project" in cfg and isinstance(cfg["project"].get("description"), str):
        cfg["project"]["description"] = DoubleQuotedScalarString(cfg["project"]["description"])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    with out_path.open("w", encoding="utf-8") as f:
        yaml.dump(cfg, f)
